     1→/**
     2→ * Unified Task Service
     3→ *
     4→ * This module provides a thin async wrapper around task/ops functions
     5→ * for backward compatibility with gateway routes.
     6→ *
     7→ * Type Hierarchy:
     8→ * - All types are defined in: task/ops/types.ts
     9→ * - TaskEventType is in: task/events/event-types.ts (re-exported from types.ts)
    10→ *
    11→ * All tasks are stored in: .viben/tasks/<date>-<slug>/task.json
    12→ */
    13→import { join, basename } from "node:path";
    14→import { mkdir, readFile, writeFile, readdir, rm, stat } from "node:fs/promises";
    15→import { existsSync } from "node:fs";
    16→import { taskLock } from "../utils/async-lock";
    17→
    18→// =============================================================================
    19→// Re-export all types from task/ops/types.ts
    20→// This ensures backward compatibility - external consumers can still import
    21→// all types from task/service.ts
    22→// =============================================================================
    23→
    24→export type {
    25→  // Core status types
    26→  TaskStatus,
    27→  ReviewReason,
    28→  SubtaskStatus,
    29→  SubtaskInfo,
    30→  ExecutionPhase,
    31→  ExecutionProgress,
    32→  // XState types
    33→  XStateValue,
    34→  TaskEvent,
    35→  // Metadata types
    36→  TaskSource,
    37→  TaskClassification,
    38→  AgentConfig,
    39→  GitConfig,
    40→  TaskMetadata,
    41→  // Core task interface
    42→  UnifiedTask,
    43→  // Log types
    44→  TaskLogEntryType,
    45→  TaskLogEntry,
    46→  TaskLogPhaseStatus,
    47→  TaskLogPhase,
    48→  TaskLogs,
    49→  // Implementation plan types
    50→  ImplementationPlanSubtask,
    51→  ImplementationPlanFile,
    52→  ImplementationPlanSubtaskV2,
    53→  ImplementationPhase,
    54→  ImplementationProgress,
    55→  ImplementationPlanFileV2,
    56→  TaskSpecsData,
    57→} from "./ops/types";
    58→
    59→// Re-export TaskEventType from event-types.ts
    60→export { TaskEventType, VALID_EVENT_TYPES, isValidEventType } from "./events/event-types";
    61→
    62→// Re-export status constants and validation
    63→export { VALID_TASK_STATUSES, isValidTaskStatus } from "./ops/types";
    64→
    65→// Re-export priority types and constants
    66→export type { IssuePriority } from "./ops/types";
    67→export { PRIORITY_ORDER, DEFAULT_PRIORITY } from "./ops/types";
    68→
    69→// Import types for internal use
    70→import type {
    71→  UnifiedTask,
    72→  TaskStatus,
    73→  ReviewReason,
    74→  TaskLogEntryType,
    75→  TaskLogEntry,
    76→  TaskLogPhase,
    77→  TaskLogs,
    78→  TaskSpecsData,
    79→  ImplementationPlanSubtask,
    80→  ImplementationPlanFile,
    81→} from "./ops/types";
    82→import { isValidTaskStatus } from "./ops/types";
    83→
    84→// =============================================================================
    85→// Constants
    86→// =============================================================================
    87→
    88→const DIR_VIBEN = ".viben";
    89→const DIR_TASKS = "tasks";
    90→const FILE_TASK_JSON = "task.json";
    91→
    92→// =============================================================================
    93→// Task Service Class
    94→// =============================================================================
    95→
    96→/**
    97→ * Unified Task Service
    98→ *
    99→ * All tasks are stored in workspace directories:
   100→ * <workspace>/.viben/tasks/<date>-<slug>/task.json
   101→ */
   102→export class TaskService {
   103→  // ==========================================================================
   104→  // Path Helpers
   105→  // ==========================================================================
   106→
   107→  /**
   108→   * Get the tasks directory for a workspace
   109→   */
   110→  private tasksDir(workspacePath: string): string {
   111→    return join(workspacePath, DIR_VIBEN, DIR_TASKS);
   112→  }
   113→
   114→  /**
   115→   * Get the task.json path for a task directory
   116→   */
   117→  private taskJsonPath(taskDir: string): string {
   118→    return join(taskDir, FILE_TASK_JSON);
   119→  }
   120→
   121→  /**
   122→   * Generate a date prefix for task directories (MM-DD format)
   123→   */
   124→  private getDatePrefix(): string {
   125→    const now = new Date();
   126→    const month = String(now.getMonth() + 1).padStart(2, "0");
   127→    const day = String(now.getDate()).padStart(2, "0");
   128→    return `${month}-${day}`;
   129→  }
   130→
   131→  /**
   132→   * Generate a URL-safe slug from a string
   133→   */
   134→  private slugify(input: string): string {
   135→    return input
   136→      .toLowerCase()
   137→      .replace(/[^a-z0-9]/g, "-")
   138→      .replace(/-+/g, "-")
   139→      .replace(/^-|-$/g, "");
   140→  }
   141→
   142→  /**
   143→   * Generate a unique task ID
   144→   */
   145→  private generateTaskId(): string {
   146→    return `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
   147→  }
   148→
   149→  // ==========================================================================
   150→  // Core CRUD Operations
   151→  // ==========================================================================
   152→
   153→  /**
   154→   * Get a task from a task directory
   155→   *
   156→   * @param taskDir - Absolute path to task directory
   157→   * @returns Task data or null if not found
   158→   */
   159→  async getTask(taskDir: string): Promise<UnifiedTask | null> {
   160→    const jsonPath = this.taskJsonPath(taskDir);
   161→
   162→    if (!existsSync(jsonPath)) {
   163→      return null;
   164→    }
   165→
   166→    try {
   167→      const content = await readFile(jsonPath, "utf-8");
   168→      const data = JSON.parse(content) as UnifiedTask;
   169→
   170→      // Normalize legacy status values
   171→      if (data.status) {
   172→        const normalizedStatus = this.normalizeStatus(data.status as string);
   173→        if (normalizedStatus !== data.status) {
   174→          data.status = normalizedStatus;
   175→        }
   176→      }
   177→
   178→      return data;
   179→    } catch {
   180→      return null;
   181→    }
   182→  }
   183→
   184→  /**
   185→   * Create a new task in a workspace
   186→   *
   187→   * @param workspacePath - Absolute path to workspace
   188→   * @param task - Partial task data (id, name, title are required or generated)
   189→   * @returns Object with taskDir and task data
   190→   */
   191→  async createTask(
   192→    workspacePath: string,
   193→    task: Partial<UnifiedTask>
   194→  ): Promise<{ taskDir: string; task: UnifiedTask }> {
   195→    const tasksDir = this.tasksDir(workspacePath);
   196→
   197→    // Ensure tasks directory exists
   198→    await mkdir(tasksDir, { recursive: true });
   199→
   200→    // Generate slug from title or use provided name
   201→    const slug = task.name || (task.title ? this.slugify(task.title) : this.generateTaskId());
   202→    const datePrefix = this.getDatePrefix();
   203→    const dirName = `${datePrefix}-${slug}`;
   204→    const taskDir = join(tasksDir, dirName);
   205→
   206→    // Create task directory
   207→    await mkdir(taskDir, { recursive: true });
   208→
   209→    const now = new Date().toISOString();
   210→    const today = now.split("T")[0];
   211→
   212→    // Build full task object
   213→    const fullTask: UnifiedTask = {
   214→      id: task.id || this.generateTaskId(),
   215→      name: slug,
   216→      title: task.title || slug,
   217→      description: task.description,
   218→      status: task.status || "backlog",
   219→      review_reason: task.review_reason,
   220→      current_phase: task.current_phase ?? 0,
   221→      next_action: task.next_action ?? [
   222→        { phase: 1, action: "implement" },
   223→        { phase: 2, action: "check" },
   224→        { phase: 3, action: "finish" },
   225→      ],
   226→      priority: task.priority || "medium",
   227→      creator: task.creator,
   228→      assignee: task.assignee,
   229→      branch: task.branch,
   230→      base_branch: task.base_branch,
   231→      worktree_path: task.worktree_path,
   232→      commit: task.commit,
   233→      pr_url: task.pr_url,
   234→      subtasks: task.subtasks ?? [],
   235→      related_files: task.related_files ?? [],
   236→      notes: task.notes ?? "",
   237→      agent: task.agent,
   238→      session_id: task.session_id,
   239→      task_index: task.task_index ?? 0,
   240→      prompt: task.prompt,
   241→      cost: task.cost,
   242→      duration: task.duration,
   243→      favorite: task.favorite,
   244→      executor: task.executor,
   245→      workspace_path: workspacePath,
   246→      created_at: task.created_at || today,
   247→      updated_at: now,
   248→      completed_at: task.completed_at,
   249→    };
   250→
   251→    // Write task.json
   252→    const jsonPath = this.taskJsonPath(taskDir);
   253→    await writeFile(jsonPath, JSON.stringify(fullTask, null, 2), "utf-8");
   254→
   255→    return { taskDir, task: fullTask };
   256→  }
   257→
   258→  /**
   259→   * Update a task
   260→   *
   261→   * Note: This method does NOT acquire a lock. State transitions should go
   262→   * through `taskEventStore.applyEvent()` which has its own locking.
   263→   * This method is for updating non-state fields (metadata, session_id, etc.)
   264→   * where last-write-wins semantics are acceptable.
   265→   *
   266→   * @param taskDir - Absolute path to task directory
   267→   * @param updates - Partial task data to update
   268→   * @returns Updated task data
   269→   */
   270→  async updateTask(taskDir: string, updates: Partial<UnifiedTask>): Promise<UnifiedTask> {
   271→    const existing = await this.getTask(taskDir);
   272→    if (!existing) {
   273→      throw new Error(`Task not found: ${taskDir}`);
   274→    }
   275→
   276→    // Validate and normalize status to prevent invalid values like "done" (SSE message type)
   277→    // Even though the type system says TaskStatus, runtime values could be invalid
   278→    if (updates.status !== undefined) {
   279→      const statusAsString = updates.status as string;
   280→      if (!isValidTaskStatus(statusAsString)) {
   281→        // "done" is an SSE message type, not a task status - map it to "completed"
   282→        if (statusAsString === "done") {
   283→          updates = { ...updates, status: "completed" };
   284→          console.warn(`[TaskService.updateTask] Invalid status "done" normalized to "completed" for task: ${taskDir}`);
   285→        } else {
   286→          // Unknown invalid status - default to "backlog"
   287→          updates = { ...updates, status: "backlog" };
   288→          console.warn(`[TaskService.updateTask] Invalid status "${statusAsString}" normalized to "backlog" for task: ${taskDir}`);
   289→        }
   290→      }
   291→    }
   292→
   293→    // Configuration locking: agent/sessionId/executor/model cannot be changed after task is queued
   294→    if (existing.status !== "backlog") {
   295→      const lockedFields = ["agent", "session_id", "executor", "model"] as const;
   296→      for (const field of lockedFields) {
   297→        if (updates[field] !== undefined && updates[field] !== existing[field]) {
   298→          throw new Error(
   299→            `Cannot modify '${field}' after task is queued. ` +
   300→            `Task status is '${existing.status}', locked fields can only be changed in 'backlog' status.`
   301→          );
   302→        }
   303→      }
   304→    }
   305→
   306→    const now = new Date().toISOString();
   307→
   308→    // Build updated task
   309→    const updated: UnifiedTask = {
   310→      ...existing,
   311→      ...updates,
   312→      id: existing.id, // Prevent ID from being changed
   313→      name: existing.name, // Prevent name from being changed
   314→      updated_at: now,
   315→    };
   316→
   317→    // Set completedAt if status changed to a terminal state (completed, failed, cancelled)
   318→    if (
   319→      updates.status &&
   320→      (updates.status === "completed" || updates.status === "failed" || updates.status === "cancelled") &&
   321→      existing.status !== updates.status
   322→    ) {
   323→      updated.completed_at = now;
   324→    }
   325→
   326→    // Write updated task.json
   327→    const jsonPath = this.taskJsonPath(taskDir);
   328→    await writeFile(jsonPath, JSON.stringify(updated, null, 2), "utf-8");
   329→
   330→    return updated;
   331→  }
   332→
   333→  /**
   334→   * Delete a task
   335→   *
   336→   * @param taskDir - Absolute path to task directory
   337→   * @returns True if deleted
   338→   */
   339→  async deleteTask(taskDir: string): Promise<boolean> {
   340→    if (!existsSync(taskDir)) {
   341→      return false;
   342→    }
   343→
   344→    try {
   345→      await rm(taskDir, { recursive: true });
   346→      return true;
   347→    } catch {
   348→      return false;
   349→    }
   350→  }
   351→
   352→  /**
   353→   * List all tasks in a workspace
   354→   *
   355→   * @param workspacePath - Absolute path to workspace
   356→   * @param options - Options for listing tasks
   357→   * @param options.includeArchived - Include tasks from archive directory (default: true)
   358→   * @returns Array of tasks
   359→   */
   360→  async listTasks(
   361→    workspacePath: string,
   362→    options: { includeArchived?: boolean } = {}
   363→  ): Promise<UnifiedTask[]> {
   364→    const { includeArchived = true } = options;
   365→    const tasksDir = this.tasksDir(workspacePath);
   366→
   367→    if (!existsSync(tasksDir)) {
   368→      return [];
   369→    }
   370→
   371→    const tasks: UnifiedTask[] = [];
   372→
   373→    try {
   374→      const entries = await readdir(tasksDir, { withFileTypes: true });
   375→
   376→      for (const entry of entries) {
   377→        // Skip non-directories
   378→        if (!entry.isDirectory()) {
   379→          continue;
   380→        }
   381→
   382→        // Handle archive directory separately
   383→        if (entry.name === "archive") {
   384→          if (includeArchived) {
   385→            const archivedTasks = await this.listArchivedTasks(workspacePath);
   386→            tasks.push(...archivedTasks);
   387→          }
   388→          continue;
   389→        }
   390→
   391→        const taskDir = join(tasksDir, entry.name);
   392→        const task = await this.getTask(taskDir);
   393→        if (task) {
   394→          // Ensure workspacePath is set
   395→          task.workspace_path = task.workspace_path || workspacePath;
   396→          tasks.push(task);
   397→        }
   398→      }
   399→    } catch {
   400→      // Ignore errors
   401→    }
   402→
   403→    // Sort by created_at descending
   404→    tasks.sort((a, b) => {
   405→      const dateA = new Date(a.created_at || "").getTime();
   406→      const dateB = new Date(b.created_at || "").getTime();
   407→      return dateB - dateA;
   408→    });
   409→
   410→    return tasks;
   411→  }
   412→
   413→  /**
   414→   * List archived tasks from .viben/tasks/archive/
   415→   *
   416→   * Archive structure: archive/{year-month}/{task-dir}/task.json
   417→   * e.g., archive/2026-01/01-15-my-task/task.json
   418→   *
   419→   * @param workspacePath - Absolute path to workspace
   420→   * @returns Array of archived tasks
   421→   */
   422→  async listArchivedTasks(workspacePath: string): Promise<UnifiedTask[]> {
   423→    const archiveDir = join(this.tasksDir(workspacePath), "archive");
   424→
   425→    if (!existsSync(archiveDir)) {
   426→      return [];
   427→    }
   428→
   429→    const tasks: UnifiedTask[] = [];
   430→
   431→    try {
   432→      // List year-month directories (e.g., 2026-01, 2026-02)
   433→      const monthDirs = await readdir(archiveDir, { withFileTypes: true });
   434→
   435→      for (const monthDir of monthDirs) {
   436→        if (!monthDir.isDirectory()) {
   437→          continue;
   438→        }
   439→
   440→        const monthPath = join(archiveDir, monthDir.name);
   441→
   442→        // List task directories within each month
   443→        const taskDirs = await readdir(monthPath, { withFileTypes: true });
   444→
   445→        for (const taskEntry of taskDirs) {
   446→          if (!taskEntry.isDirectory()) {
   447→            continue;
   448→          }
   449→
   450→          const taskDir = join(monthPath, taskEntry.name);
   451→          const task = await this.getTask(taskDir);
   452→          if (task) {
   453→            // Ensure workspacePath is set and status is archived
   454→            task.workspace_path = task.workspace_path || workspacePath;
   455→            // Mark as archived if not already
   456→            if (task.status !== "archived") {
   457→              task.status = "archived";
   458→            }
   459→            tasks.push(task);
   460→          }
   461→        }
   462→      }
   463→    } catch {
   464→      // Ignore errors
   465→    }
   466→
   467→    return tasks;
   468→  }
   469→
   470→  /**
   471→   * Find a task by name in a workspace
   472→   *
   473→   * Supports:
   474→   * - Exact match: "01-31-my-task"
   475→   * - Suffix match: "my-task" matches "01-31-my-task"
   476→   *
   477→   * @param workspacePath - Absolute path to workspace
   478→   * @param name - Task name to find
   479→   * @returns Absolute path to task directory, or null if not found
   480→   */
   481→  async findTaskByName(workspacePath: string, name: string): Promise<string | null> {
   482→    const tasksDir = this.tasksDir(workspacePath);
   483→
   484→    if (!name || !existsSync(tasksDir)) {
   485→      return null;
   486→    }
   487→
   488→    // Try exact match first
   489→    const exactPath = join(tasksDir, name);
   490→    if (existsSync(exactPath)) {
   491→      try {
   492→        const stats = await stat(exactPath);
   493→        if (stats.isDirectory()) {
   494→          return exactPath;
   495→        }
   496→      } catch {
   497→        // Ignore
   498→      }
   499→    }
   500→
   501→    // Try suffix match
   502→    try {
   503→      const entries = await readdir(tasksDir, { withFileTypes: true });
   504→      for (const entry of entries) {
   505→        if (entry.isDirectory() && entry.name.endsWith(`-${name}`)) {
   506→          return join(tasksDir, entry.name);
   507→        }
   508→      }
   509→    } catch {
   510→      // Ignore
   511→    }
   512→
   513→    return null;
   514→  }
   515→
   516→  /**
   517→   * Find a task by ID in a workspace
   518→   *
   519→   * Searches both active tasks and archived tasks.
   520→   *
   521→   * @param workspacePath - Absolute path to workspace
   522→   * @param id - Task ID to find
   523→   * @returns Task directory path or null
   524→   */
   525→  async findTaskById(workspacePath: string, id: string): Promise<string | null> {
   526→    const tasksDir = this.tasksDir(workspacePath);
   527→
   528→    if (!existsSync(tasksDir)) {
   529→      return null;
   530→    }
   531→
   532→    // Search active tasks first
   533→    try {
   534→      const entries = await readdir(tasksDir, { withFileTypes: true });
   535→      for (const entry of entries) {
   536→        if (!entry.isDirectory() || entry.name === "archive") {
   537→          continue;
   538→        }
   539→        const taskDir = join(tasksDir, entry.name);
   540→        const task = await this.getTask(taskDir);
   541→        if (task && task.id === id) {
   542→          return taskDir;
   543→        }
   544→      }
   545→    } catch {
   546→      // Ignore
   547→    }
   548→
   549→    // Search archived tasks
   550→    const archiveDir = join(tasksDir, "archive");
   551→    if (existsSync(archiveDir)) {
   552→      try {
   553→        const monthDirs = await readdir(archiveDir, { withFileTypes: true });
   554→        for (const monthDir of monthDirs) {
   555→          if (!monthDir.isDirectory()) {
   556→            continue;
   557→          }
   558→          const monthPath = join(archiveDir, monthDir.name);
   559→          const taskDirs = await readdir(monthPath, { withFileTypes: true });
   560→          for (const taskEntry of taskDirs) {
   561→            if (!taskEntry.isDirectory()) {
   562→              continue;
   563→            }
   564→            const taskDir = join(monthPath, taskEntry.name);
   565→            const task = await this.getTask(taskDir);
   566→            if (task && task.id === id) {
   567→              return taskDir;
   568→            }
   569→          }
   570→        }
   571→      } catch {
   572→        // Ignore
   573→      }
   574→    }
   575→
   576→    return null;
   577→  }
   578→
   579→  // ==========================================================================
   580→  // Status Helpers
   581→  // ==========================================================================
   582→
   583→  /**
   584→   * Check if a status is a settled state (no automatic transitions)
   585→   */
   586→  isSettledState(status: TaskStatus): boolean {
   587→    return ["backlog", "paused", "review", "completed", "failed", "cancelled", "archived"].includes(status);
   588→  }
   589→
   590→  /**
   591→   * Check if a status is an active state (task is being worked on)
   592→   */
   593→  isActiveState(status: TaskStatus): boolean {
   594→    return ["queue", "in_progress", "paused"].includes(status);
   595→  }
   596→
   597→  /**
   598→   * Check if a task is completed
   599→   */
   600→  isCompleted(task: UnifiedTask): boolean {
   601→    if (task.status === "completed") {
   602→      return true;
   603→    }
   604→    if (task.status === "review" && task.review_reason === "completed") {
   605→      return true;
   606→    }
   607→    return false;
   608→  }
   609→
   610→  /**
   611→   * Normalize a status value to the unified TaskStatus
   612→   */
   613→  normalizeStatus(status: string): TaskStatus {
   614→    if (isValidTaskStatus(status)) {
   615→      return status;
   616→    }
   617→
   618→    // Default for invalid status
   619→    return "backlog";
   620→  }
   621→
   622→  // ==========================================================================
   623→  // Compatibility Methods
   624→  // ==========================================================================
   625→
   626→  /**
   627→   * Get the directory name from a task directory path
   628→   */
   629→  getTaskDirName(taskDir: string): string {
   630→    return basename(taskDir);
   631→  }
   632→
   633→  /**
   634→   * Get the tasks directory path for a workspace
   635→   */
   636→  getTasksDir(workspacePath: string): string {
   637→    return this.tasksDir(workspacePath);
   638→  }
   639→
   640→  // ==========================================================================
   641→  // Task Specs Data (PRD, Logs, Task Dir)
   642→  // ==========================================================================
   643→
   644→  /**
   645→   * Get task specs data from the task directory
   646→   *
   647→   * Reads:
   648→   * - prd.md (PRD content)
   649→   * - implementation_plan.json (subtasks)
   650→   * - logs/ directory (execution logs)
   651→   * - Returns task_dir path for file browsing
   652→   *
   653→   * @param taskDir - Absolute path to task directory
   654→   * @returns TaskSpecsData object
   655→   */
   656→  async getTaskSpecsData(taskDir: string): Promise<TaskSpecsData> {
   657→    const result: TaskSpecsData = {
   658→      prd_content: null,
   659→      prd_path: null,
   660→      subtasks: [],
   661→      logs: null,
   662→      task_dir: taskDir, // Return task directory path for file browsing
   663→    };
   664→
   665→    // 1. Read PRD content (prd.md)
   666→    const prdPath = join(taskDir, "prd.md");
   667→    if (existsSync(prdPath)) {
   668→      try {
   669→        result.prd_content = await readFile(prdPath, "utf-8");
   670→        result.prd_path = prdPath;
   671→      } catch {
   672→        // Ignore read errors
   673→      }
   674→    }
   675→
   676→    // 2. Read implementation plan (implementation_plan.json)
   677→    const planPath = join(taskDir, "implementation_plan.json");
   678→    if (existsSync(planPath)) {
   679→      try {
   680→        const planContent = await readFile(planPath, "utf-8");
   681→        const plan = JSON.parse(planContent) as ImplementationPlanFile;
   682→        result.subtasks = plan.subtasks || [];
   683→      } catch {
   684→        // Ignore parse errors
   685→      }
   686→    }
   687→
   688→    // 3. Read logs from logs/ directory
   689→    const logsDir = join(taskDir, "logs");
   690→    if (existsSync(logsDir)) {
   691→      try {
   692→        const logEntries = await readdir(logsDir, { withFileTypes: true });
   693→        const phases: TaskLogPhase[] = [];
   694→
   695→        // Standard phase files
   696→        const standardPhases = ["plan", "implement", "check"];
   697→
   698→        for (const entry of logEntries) {
   699→          if (entry.isFile() && entry.name.endsWith(".log")) {
   700→            const phaseName = entry.name.replace(".log", "");
   701→            const logPath = join(logsDir, entry.name);
   702→
   703→            try {
   704→              const logContent = await readFile(logPath, "utf-8");
   705→              const entries = this.parseLogContent(logContent, phaseName);
   706→
   707→              // Determine phase status
   708→              let status: TaskLogPhase["status"] = "pending";
   709→              if (entries.length > 0) {
   710→                const hasError = entries.some((e) => e.type === "error");
   711→                const hasSuccess = entries.some((e) => e.type === "success");
   712→                if (hasError) status = "failed";
   713→                else if (hasSuccess) status = "complete";
   714→                else status = "running";
   715→              }
   716→
   717→              phases.push({
   718→                id: phaseName,
   719→                name: phaseName.charAt(0).toUpperCase() + phaseName.slice(1),
   720→                status,
   721→                entries,
   722→                order: standardPhases.indexOf(phaseName),
   723→              });
   724→            } catch {
   725→              // Ignore unreadable files
   726→            }
   727→          }
   728→        }
   729→
   730→        // Sort by order (standard phases first)
   731→        phases.sort((a, b) => {
   732→          const orderA = a.order !== undefined && a.order >= 0 ? a.order : 999;
   733→          const orderB = b.order !== undefined && b.order >= 0 ? b.order : 999;
   734→          return orderA - orderB;
   735→        });
   736→
   737→        if (phases.length > 0) {
   738→          result.logs = { phases };
   739→        }
   740→      } catch {
   741→        // Ignore errors
   742→      }
   743→    }
   744→
   745→    return result;
   746→  }
   747→
   748→  /**
   749→   * Parse log file content into structured log entries
   750→   */
   751→  private parseLogContent(content: string, phaseId: string): TaskLogEntry[] {
   752→    const entries: TaskLogEntry[] = [];
   753→    const lines = content.split("\n").filter((line) => line.trim());
   754→
   755→    for (const line of lines) {
   756→      // Try to parse structured format: [timestamp] [level] message
   757→      const match = line.match(/^\[([^\]]+)\]\s*\[([^\]]+)\]\s*(.*)$/);
   758→
   759→      if (match) {
   760→        const [, timestamp, level, message] = match;
   761→        entries.push({
   762→          id: `${phaseId}-${entries.length}`,
   763→          type: this.mapLogLevel(level),
   764→          message,
   765→          timestamp: timestamp || new Date().toISOString(),
   766→        });
   767→      } else {
   768→        // Fallback: plain text
   769→        entries.push({
   770→          id: `${phaseId}-${entries.length}`,
   771→          type: "text",
   772→          message: line,
   773→          timestamp: new Date().toISOString(),
   774→        });
   775→      }
   776→    }
   777→
   778→    return entries;
   779→  }
   780→
   781→  /**
   782→   * Map log level string to entry type
   783→   */
   784→  private mapLogLevel(level: string): TaskLogEntryType {
   785→    const normalized = level.toLowerCase().trim();
   786→    switch (normalized) {
   787→      case "error":
   788→      case "err":
   789→        return "error";
   790→      case "warn":
   791→      case "warning":
   792→        return "warning";
   793→      case "success":
   794→      case "ok":
   795→        return "success";
   796→      case "info":
   797→        return "info";
   798→      case "tool_start":
   799→      case "start":
   800→        return "tool_start";
   801→      case "tool_end":
   802→      case "end":
   803→        return "tool_end";
   804→      default:
   805→        return "text";
   806→    }
   807→  }
   808→}
