   216→/**
   217→ * Format duration in milliseconds to human readable string
   218→ * Examples: "5s", "2m 30s", "1h 15m", "2d 3h"
   219→ */
   220→function formatDuration(ms: number): string {
   221→  if (ms < 0) return "-";
   222→
   223→  const seconds = Math.floor(ms / 1000);
   224→  const minutes = Math.floor(seconds / 60);
   225→  const hours = Math.floor(minutes / 60);
   226→  const days = Math.floor(hours / 24);
   227→
   228→  if (days > 0) {
   229→    const remainingHours = hours % 24;
   230→    return remainingHours > 0 ? `${days}d ${remainingHours}h` : `${days}d`;
   231→  }
   232→  if (hours > 0) {
   233→    const remainingMinutes = minutes % 60;
   234→    return remainingMinutes > 0 ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
   235→  }
   236→  if (minutes > 0) {
   237→    const remainingSeconds = seconds % 60;
   238→    return remainingSeconds > 0 ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
   239→  }
   240→  return `${seconds}s`;
   241→}
   242→
   243→/**
   244→ * Get first and last timestamp from a JSONL log file
   245→ * Returns [firstTimestamp, lastTimestamp] or [null, null] if file doesn't exist
   246→ */
   247→function getLogTimeRange(logPath: string): [string | null, string | null] {
   248→  if (!existsSync(logPath)) {
   249→    return [null, null];
   250→  }
   251→
   252→  try {
   253→    const content = readFileSync(logPath, "utf-8").trim();
   254→    if (!content) {
   255→      return [null, null];
   256→    }
   257→
   258→    const lines = content.split("\n").filter((line) => line.trim());
   259→    if (lines.length === 0) {
   260→      return [null, null];
   261→    }
   262→
   263→    let firstTimestamp: string | null = null;
   264→    let lastTimestamp: string | null = null;
   265→
   266→    // Get first timestamp
   267→    for (const line of lines) {
   268→      try {
   269→        const entry = JSON.parse(line);
   270→        if (entry.timestamp) {
   271→          firstTimestamp = entry.timestamp;
   272→          break;
   273→        }
   274→      } catch {
   275→        // Skip invalid JSON lines
   276→      }
   277→    }
   278→
   279→    // Get last timestamp (iterate from end)
   280→    for (let i = lines.length - 1; i >= 0; i--) {
   281→      try {
   282→        const entry = JSON.parse(lines[i]);
   283→        if (entry.timestamp) {
   284→          lastTimestamp = entry.timestamp;
   285→          break;
   286→        }
   287→      } catch {
   288→        // Skip invalid JSON lines
   289→      }
   290→    }
   291→
   292→    return [firstTimestamp, lastTimestamp];
   293→  } catch {
   294→    return [null, null];
   295→  }
   296→}
   297→
   298→/**
   299→ * Calculate timing info from task data and log files
   300→ */
   301→function calculateTiming(
   302→  taskData: Record<string, unknown>,
   303→  taskDir: string,
   304→  files: {
   305→    start_log: TaskFileInfo;
   306→    plan_log: TaskFileInfo;
   307→    work_log: TaskFileInfo;
   308→    implement_log: TaskFileInfo;
   309→    review_log: TaskFileInfo;
   310→  }
   311→): TaskTimingInfo {
   312→  const timing: TaskTimingInfo = {};
   313→  const now = Date.now();
   314→
   315→  const createdAt = taskData.created_at as string | undefined;
   316→  const queuedAt = taskData.queued_at as string | undefined;
   317→  const startedAt = taskData.started_at as string | undefined;
   318→  const checkPassedAt = taskData.check_passed_at as string | undefined;
   319→  const prCreatedAt = taskData.pr_created_at as string | undefined;
   320→  const completedAt = taskData.completed_at as string | undefined;
   321→  const status = taskData.status as string | undefined;
   322→
   323→  // 1. Total duration (creation to now or completion)
   324→  if (createdAt) {
   325→    const endTime = completedAt ? new Date(completedAt).getTime() : now;
   326→    const startTime = new Date(createdAt).getTime();
   327→    timing.totalDuration = endTime - startTime;
   328→    timing.totalDurationStr = formatDuration(timing.totalDuration);
   329→  }
   330→
   331→  // 2. Queue duration (queuedAt to startedAt or first log activity)
   332→  if (queuedAt) {
   333→    // Prefer startedAt timestamp if available
   334→    if (startedAt) {
   335→      const queueTime = new Date(queuedAt).getTime();
   336→      const startTime = new Date(startedAt).getTime();
   337→      timing.queueDuration = startTime - queueTime;
   338→      timing.queueDurationStr = formatDuration(timing.queueDuration);
   339→    } else {
   340→      // Fall back to log file timestamps
   341→      const [startLogFirst] = getLogTimeRange(join(taskDir, "start.log.jsonl"));
   342→      const [planLogFirst] = getLogTimeRange(join(taskDir, "plan.log.jsonl"));
   343→      const [workLogFirst] = getLogTimeRange(join(taskDir, "work.log.jsonl"));
   344→
   345→      const executionStart = startLogFirst || planLogFirst || workLogFirst;
   346→      if (executionStart) {
   347→        const queueTime = new Date(queuedAt).getTime();
   348→        const execTime = new Date(executionStart).getTime();
   349→        timing.queueDuration = execTime - queueTime;
   350→        timing.queueDurationStr = formatDuration(timing.queueDuration);
   351→      }
   352→    }
   353→  }
   354→
   355→  // 3. Plan phase duration
   356→  const [planFirst, planLast] = getLogTimeRange(join(taskDir, "plan.log.jsonl"));
   357→  if (planFirst && planLast) {
   358→    timing.planDuration = new Date(planLast).getTime() - new Date(planFirst).getTime();
   359→    timing.planDurationStr = formatDuration(timing.planDuration);
   360→  }
   361→
   362→  // 4. Implementation phase duration (from implement.log or work.log)
   363→  const [implFirst, implLast] = getLogTimeRange(join(taskDir, "implement.log.jsonl"));
   364→  const [workFirst, workLast] = getLogTimeRange(join(taskDir, "work.log.jsonl"));
   365→
   366→  // Use implement.log if exists, otherwise work.log
   367→  if (implFirst && implLast) {
   368→    timing.implementDuration = new Date(implLast).getTime() - new Date(implFirst).getTime();
   369→    timing.implementDurationStr = formatDuration(timing.implementDuration);
   370→  } else if (workFirst && workLast) {
   371→    timing.implementDuration = new Date(workLast).getTime() - new Date(workFirst).getTime();
   372→    timing.implementDurationStr = formatDuration(timing.implementDuration);
   373→  }
   374→
   375→  // 5. Check/review phase duration
   376→  const [reviewFirst, reviewLast] = getLogTimeRange(join(taskDir, "review.log.jsonl"));
   377→  if (reviewFirst && reviewLast) {
   378→    timing.checkDuration = new Date(reviewLast).getTime() - new Date(reviewFirst).getTime();
   379→    timing.checkDurationStr = formatDuration(timing.checkDuration);
   380→  }
   381→
   382→  // 6. Total execution duration (from startedAt or first activity to now/completion)
   383→  let executionStartTime: number | null = null;
   384→  if (startedAt) {
   385→    executionStartTime = new Date(startedAt).getTime();
   386→  } else {
   387→    const allStarts = [
   388→      files.start_log.modifiedAt,
   389→      files.plan_log.modifiedAt,
   390→      files.work_log.modifiedAt,
   391→      files.implement_log.modifiedAt,
   392→    ]
   393→      .filter(Boolean)
   394→      .map((t) => new Date(t!).getTime());
   395→
   396→    if (allStarts.length > 0) {
   397→      executionStartTime = Math.min(...allStarts);
   398→    }
   399→  }
   400→
   401→  if (executionStartTime) {
   402→    const endTime = completedAt ? new Date(completedAt).getTime() : now;
   403→    timing.executionDuration = endTime - executionStartTime;
   404→    timing.executionDurationStr = formatDuration(timing.executionDuration);
   405→  }
   406→
   407→  // 7. Idle duration (time since last activity)
   408→  const allEnds = [
   409→    files.start_log.modifiedAt,
   410→    files.plan_log.modifiedAt,
   411→    files.work_log.modifiedAt,
   412→    files.implement_log.modifiedAt,
   413→    files.review_log.modifiedAt,
   414→    checkPassedAt,
   415→    prCreatedAt,
   416→  ]
   417→    .filter(Boolean)
   418→    .map((t) => new Date(t!).getTime());
   419→
   420→  if (allEnds.length > 0 && status !== "completed" && status !== "archived") {
   421→    const lastActivity = Math.max(...allEnds);
   422→    timing.idleDuration = now - lastActivity;
   423→    timing.idleDurationStr = formatDuration(timing.idleDuration);
   424→  }
   425→
   426→  return timing;
   427→}
