   463→  const { mine, status } = options;
   464→
   465→  const developer = getDeveloper(repoRoot);
   466→
   467→  // Check filters
   468→  if (mine && !developer) {
   469→    return {
   470→      success: false,
   471→      tasks: [],
   472→      error: "No developer set. Run init-developer first or remove --mine flag",
   473→    };
   474→  }
   475→
   476→  // Get all active tasks
   477→  let tasks = getActiveTasks(repoRoot);
   478→
   479→  // Apply --mine filter
   480→  if (mine && developer) {
   481→    tasks = tasks.filter((t) => t.assignee === developer);
   482→  }
   483→
   484→  // Apply --status filter
   485→  if (status) {
   486→    tasks = tasks.filter((t) => t.status === status);
   487→  }
   488→
   489→  return {
   490→    success: true,
   491→    tasks,
   492→  };
   493→}
