   499→/**
   500→ * Create a new task
   501→ */
   502→export function createTask(
   503→  repoRoot: string,
   504→  title: string,
   505→  options: CreateTaskOptions = {}
   506→): CreateTaskResult {
   507→  // Get developer for assignee and creator
   508→  const developer = getDeveloper(repoRoot);
   509→  const assignee = options.assignee || developer;
   510→
   511→  if (!assignee) {
   512→    return {
   513→      success: false,
   514→      error: "No developer set. Run init-developer first or use --assignee",
   515→    };
   516→  }
   517→
   518→  const creator = developer || assignee;
   519→
   520→  // Generate slug if not provided
   521→  const taskSlug = options.slug || slugify(title);
   522→  if (!taskSlug) {
   523→    return {
   524→      success: false,
   525→      error: "Could not generate slug from title. Use --slug to specify manually",
   526→    };
   527→  }
   528→
   529→  // Create task directory
   530→  const tasksDir = ensureTasksDir(repoRoot);
   531→  const datePrefix = getDatePrefix();
   532→  const dirName = `${datePrefix}-${taskSlug}`;
   533→  const taskDir = join(tasksDir, dirName);
   534→
   535→  const alreadyExists = existsSync(taskDir);
   536→  if (!alreadyExists) {
   537→    mkdirSync(taskDir, { recursive: true });
   538→  }
   539→
   540→  // Get current branch as base_branch (PR target)
   541→  const { stdout: branchOut } = runGitCommand(
   542→    ["branch", "--show-current"],
   543→    repoRoot
   544→  );
   545→  const currentBranch = branchOut.trim() || "main";
   546→
   547→  // Determine executor/platform
   548→  const executor = options.executor?.toUpperCase() || "CLAUDE_CODE";
   549→  const _platform: Platform = EXECUTOR_TO_PLATFORM[executor] || "claude";
   550→
   551→  // Determine branch (scope is no longer needed - title is used directly)
   552→  const branch = options.branch || `feature/${taskSlug}`;
   553→
   554→  const taskData: TaskJson = {
   555→    id: dirName,  // Use full directory name (with date prefix) as unique ID
   556→    name: taskSlug,
   557→    title: title,
   558→    description: options.description || "",
   559→    status: "backlog",
   560→    priority: (options.priority || DEFAULT_PRIORITY) as IssuePriority,
   561→    creator: creator,
   562→    assignee: assignee,
   563→    created_at: new Date().toISOString(),
   564→    completed_at: undefined,
   565→    branch: branch,
   566→    base_branch: currentBranch,
   567→    worktree_path: undefined,
   568→    current_phase: 0,
   569→    next_action: [
   570→      { phase: 1, action: "implement" },
   571→      { phase: 2, action: "check" },
   572→      { phase: 3, action: "finish" },
   573→    ],
   574→    commit: undefined,
   575→    pr_url: undefined,
   576→    subtasks: [],
   577→    related_files: [],
   578→    notes: "",
   579→    agent: options.agent,
   580→    executor: executor,
   581→    model: options.model,
   582→    auto_start: options.start || false,
   583→    worktree: options.worktree || false,
   584→    compute_reward: options.computeReward ?? false,
   585→    // Evo directory for reward config and output (reward_config is read from Evo target)
   586→    evo_dir: options.evoDir,
   587→    // Evo idea ID - links task to its source idea for reward path structure
   588→    evo_idea: options.evoIdea,
   589→  };
   590→
   591→  // Note: --start flag is handled by CLI layer calling enqueueTask after creation
   592→  // This ensures proper status transition (backlog -> queue) with queue system submission
   593→
   594→  writeTaskJson(taskDir, taskData as unknown as Record<string, unknown>);
   595→
   596→  // Initialize empty context files (to be populated by research agent)
   597→  const contextResult = initContext(repoRoot, dirName);
   598→  const contextInitialized = contextResult.success;
   599→
   600→  return {
   601→    success: true,
   602→    task_dir: taskDir,
   603→    dir_name: dirName,
   604→    status: taskData.status,
   605→    context_initialized: contextInitialized,
   606→  };
   607→}
