   613→/**
   614→ * Get file info helper
   615→ */
   616→function getFileInfo(filePath: string): TaskFileInfo {
   617→  if (!existsSync(filePath)) {
   618→    return { exists: false };
   619→  }
   620→  try {
   621→    const stats = statSync(filePath);
   622→    return {
   623→      exists: true,
   624→      size: stats.size,
   625→      modifiedAt: stats.mtime.toISOString(),
   626→    };
   627→  } catch {
   628→    return { exists: false };
   629→  }
   630→}
