   632→/**
   633→ * Get task details with extended information
   634→ */
   635→export function viewTask(repoRoot: string, taskName: string): ViewTaskResult {
   636→  const taskDir = resolveTaskDirectory(taskName, repoRoot);
   637→  if (!taskDir || !existsSync(taskDir)) {
   638→    return {
   639→      success: false,
   640→      error: `Task not found: ${taskName}`,
   641→    };
   642→  }
   643→
   644→  const taskData = readTaskJson(taskDir);
   645→  if (!taskData) {
   646→    return {
   647→      success: false,
   648→      error: `Task not found: ${taskName}`,
   649→    };
   650→  }
   651→
   652→  const dirName = basename(taskDir);
   653→
   654→  // Gather file info
   655→  const files = {
   656→    prd: getFileInfo(join(taskDir, "prd.md")),
   657→    implement_jsonl: getFileInfo(join(taskDir, "implement.jsonl")),
   658→    check_jsonl: getFileInfo(join(taskDir, "check.jsonl")),
   659→    fix_jsonl: getFileInfo(join(taskDir, "fix.jsonl")),
   660→    start_log: getFileInfo(join(taskDir, "start.log.jsonl")),
   661→    plan_log: getFileInfo(join(taskDir, "plan.log.jsonl")),
   662→    work_log: getFileInfo(join(taskDir, "work.log.jsonl")),
   663→    implement_log: getFileInfo(join(taskDir, "implement.log.jsonl")),
   664→    review_log: getFileInfo(join(taskDir, "review.log.jsonl")),
   665→  };
   666→
   667→  // Try to get runtime info from session-id.txt
   668→  let runtime: ViewTaskResult["runtime"] = { is_running: false };
   669→  const sessionIdPath = join(taskDir, "session-id.txt");
   670→  if (existsSync(sessionIdPath)) {
   671→    try {
   672→      const sessionId = readFileSync(sessionIdPath, "utf-8").trim();
   673→      if (sessionId) {
   674→        runtime.session_id = sessionId;
   675→      }
   676→    } catch {
   677→      // Ignore
   678→    }
   679→  }
   680→
   681→  // Check if task has a session_id in task.json
   682→  if (taskData.session_id) {
   683→    runtime.session_id = taskData.session_id as string;
   684→  }
   685→
   686→  // Gather worktree info
   687→  const worktree: TaskWorktreeInfo = {
   688→    enabled: taskData.worktree === true,
   689→  };
   690→
   691→  // Check worktree_path from task.json
   692→  if (taskData.worktree_path) {
   693→    worktree.path = taskData.worktree_path as string;
   694→    worktree.exists = existsSync(worktree.path);
   695→
   696→    // If worktree exists, get git status
   697→    if (worktree.exists) {
   698→      try {
   699→        // Get current branch
   700→        const branchResult = execSync("git branch --show-current", {
   701→          cwd: worktree.path,
   702→          encoding: "utf-8",
   703→          stdio: ["pipe", "pipe", "pipe"],
   704→        }).trim();
   705→        worktree.branch = branchResult || undefined;
   706→
   707→        // Check for uncommitted changes
   708→        const statusResult = execSync("git status --porcelain", {
   709→          cwd: worktree.path,
   710→          encoding: "utf-8",
   711→          stdio: ["pipe", "pipe", "pipe"],
   712→        }).trim();
   713→        const lines = statusResult ? statusResult.split("\n") : [];
   714→        worktree.uncommittedFiles = lines.length;
   715→        worktree.isDirty = lines.length > 0;
   716→      } catch {
   717→        // Git commands failed, worktree might not be a valid git repo
   718→      }
   719→    }
   720→  }
   721→
   722→  // Calculate timing info
   723→  const timing = calculateTiming(taskData, taskDir, files);
   724→
   725→  return {
   726→    success: true,
   727→    task: taskData as unknown as TaskJson,
   728→    task_dir: taskDir,
   729→    dir_name: dirName,
   730→    files,
   731→    worktree,
   732→    runtime,
   733→    timing,
   734→  };
   735→}
