   146→/**
   147→ * Get the latest journal file info from workspace directory
   148→ */
   149→function getLatestJournalInfo(dev_dir: string): {
   150→  file: string | null;
   151→  number: number;
   152→  lines: number;
   153→} {
   154→  if (!existsSync(dev_dir)) {
   155→    return { file: null, number: 0, lines: 0 };
   156→  }
   157→
   158→  let latestFile: string | null = null;
   159→  let latestNum = -1;
   160→
   161→  try {
   162→    const files = readdirSync(dev_dir);
   163→    for (const file of files) {
   164→      if (file.startsWith("journal-") && file.endsWith(".md")) {
   165→        const match = file.match(/journal-(\d+)\.md$/);
   166→        if (match) {
   167→          const num = parseInt(match[1], 10);
   168→          if (num > latestNum) {
   169→            latestNum = num;
   170→            latestFile = join(dev_dir, file);
   171→          }
   172→        }
   173→      }
   174→    }
   175→  } catch {
   176→    // Ignore errors
   177→  }
   178→
   179→  if (latestFile) {
   180→    let lines = 0;
   181→    try {
   182→      const content = readFileSync(latestFile, "utf-8");
   183→      const splitLines = content.split("\n");
   184→      if (splitLines.length > 0 && splitLines[splitLines.length - 1] === "") {
   185→        lines = splitLines.length - 1;
   186→      } else {
   187→        lines = splitLines.length;
   188→      }
   189→    } catch {
   190→      // Ignore errors
   191→    }
   192→    return { file: latestFile, number: latestNum, lines };
   193→  }
   194→
   195→  return { file: null, number: 0, lines: 0 };
   196→}
   197→
   198→/**
   199→ * Get current session number from index.md by parsing "Total Sessions" line
   200→ */
   201→function getSessionNumberFromIndex(index_path: string): number {
   202→  if (!existsSync(index_path)) {
   203→    return 0;
   204→  }
   205→
   206→  try {
   207→    const content = readFileSync(index_path, "utf-8");
   208→    for (const line of content.split("\n")) {
   209→      if (line.includes("Total Sessions")) {
   210→        const match = line.match(/:\s*(\d+)/);
   211→        if (match) {
   212→          return parseInt(match[1], 10);
   213→        }
   214→      }
   215→    }
   216→  } catch {
   217→    // Ignore errors
   218→  }
   219→
   220→  return 0;
   221→}
