   234→  const { session_num, title, commit, summary, extra_content, date } = params;
   235→
   236→  let commitTable: string;
   237→  if (commit && commit !== "-") {
   238→    const lines = ["| Hash | Message |", "|------|---------|"];
   239→    for (const c of commit.split(",")) {
   240→      const trimmed = c.trim();
   241→      lines.push(`| \`${trimmed}\` | (see git log) |`);
   242→    }
   243→    commitTable = lines.join("\n");
   244→  } else {
   245→    commitTable = "(No commits - planning session)";
   246→  }
   247→
   248→  return `
   249→
   250→## Session ${session_num}: ${title}
   251→
   252→**Date**: ${date}
   253→**Task**: ${title}
   254→
