   281→/**
   282→ * Create a new journal file when current one exceeds MAX_LINES
   283→ */
   284→function createNewJournalFileSync(
   285→  dev_dir: string,
   286→  number: number,
   287→  developer: string,
   288→  date: string,
   289→  prevNumber: number
   290→): string {
   291→  const newFilePath = join(dev_dir, `journal-${number}.md`);
   292→  const maxLines = 2000;
   293→
   294→  const content = `# Journal - ${developer} (Part ${number})
   295→
   296→> Continuation from \`journal-${prevNumber}.md\` (archived at ~${maxLines} lines)
   297→> Started: ${date}
   298→
   299→---
   300→
   301→`;
   302→
   303→  writeFileSync(newFilePath, content, "utf-8");
   304→  return newFilePath;
   305→}
