   307→/**
   308→ * Count journal files and return markdown table rows
   309→ */
   310→function countJournalFilesTable(dev_dir: string, activeNum: number): string {
   311→  const active_file = `journal-${activeNum}.md`;
   312→  const resultLines: string[] = [];
   313→
   314→  try {
   315→    const files = readdirSync(dev_dir)
   316→      .filter((f) => f.startsWith("journal-") && f.endsWith(".md"))
   317→      .sort((a, b) => {
   318→        const numA = parseInt(a.match(/(\d+)/)?.[1] ?? "0", 10);
   319→        const numB = parseInt(b.match(/(\d+)/)?.[1] ?? "0", 10);
   320→        return numB - numA;
   321→      });
   322→
   323→    for (const filename of files) {
   324→      const filePath = join(dev_dir, filename);
   325→      let lines = 0;
   326→      try {
   327→        const content = readFileSync(filePath, "utf-8");
   328→        const splitLines = content.split("\n");
   329→        if (splitLines.length > 0 && splitLines[splitLines.length - 1] === "") {
   330→          lines = splitLines.length - 1;
   331→        } else {
   332→          lines = splitLines.length;
   333→        }
   334→      } catch {
   335→        // Ignore errors
   336→      }
   337→      const status = filename === active_file ? "Active" : "Archived";
   338→      resultLines.push(`| \`${filename}\` | ~${lines} | ${status} |`);
   339→    }
   340→  } catch {
   341→    // Ignore errors
   342→  }
   343→
   344→  return resultLines.join("\n");
   345→}
