   347→/**
   348→ * Update index.md with new session info
   349→ */
   350→function updateIndexWithNewSession(params: {
   351→  index_path: string;
   352→  dev_dir: string;
   353→  session_num: number;
   354→  title: string;
   355→  commit: string;
   356→  active_file: string;
   357→  date: string;
   358→}): boolean {
   359→  const { index_path, dev_dir, session_num, title, commit, active_file, date } = params;
   360→
   361→  if (!existsSync(index_path)) {
   362→    return false;
   363→  }
   364→
   365→  let commitDisplay = "-";
   366→  if (commit && commit !== "-") {
   367→    commitDisplay = commit
   368→      .split(",")
   369→      .map((c) => `\`${c.trim()}\``)
   370→      .join(", ");
   371→  }
   372→
   373→  const match = active_file.match(/journal-(\d+)\.md$/);
   374→  const activeNum = match ? parseInt(match[1], 10) : 0;
   375→  const filesTable = countJournalFilesTable(dev_dir, activeNum);
   376→
   377→  try {
   378→    const content = readFileSync(index_path, "utf-8");
   379→
   380→    if (!content.includes("@@@auto:current-status")) {
   381→      return false;
   382→    }
   383→
   384→    const lines = content.split("\n");
   385→    const newLines: string[] = [];
   386→
   387→    let inCurrentStatus = false;
   388→    let inActiveDocuments = false;
   389→    let inSessionHistory = false;
   390→    let headerWritten = false;
   391→
   392→    for (const line of lines) {
   393→      if (line.includes("@@@auto:current-status")) {
   394→        newLines.push(line);
   395→        inCurrentStatus = true;
   396→        newLines.push(`- **Active File**: \`${active_file}\``);
   397→        newLines.push(`- **Total Sessions**: ${session_num}`);
   398→        newLines.push(`- **Last Active**: ${date}`);
   399→        continue;
   400→      }
   401→
   402→      if (line.includes("@@@/auto:current-status")) {
   403→        inCurrentStatus = false;
   404→        newLines.push(line);
   405→        continue;
   406→      }
   407→
   408→      if (line.includes("@@@auto:active-documents")) {
   409→        newLines.push(line);
   410→        inActiveDocuments = true;
   411→        newLines.push("| File | Lines | Status |");
   412→        newLines.push("|------|-------|--------|");
   413→        newLines.push(filesTable);
   414→        continue;
   415→      }
   416→
   417→      if (line.includes("@@@/auto:active-documents")) {
   418→        inActiveDocuments = false;
   419→        newLines.push(line);
   420→        continue;
   421→      }
   422→
   423→      if (line.includes("@@@auto:session-history")) {
   424→        newLines.push(line);
   425→        inSessionHistory = true;
   426→        headerWritten = false;
   427→        continue;
   428→      }
   429→
   430→      if (line.includes("@@@/auto:session-history")) {
   431→        inSessionHistory = false;
   432→        newLines.push(line);
   433→        continue;
   434→      }
   435→
   436→      if (inCurrentStatus) {
   437→        continue;
   438→      }
   439→
   440→      if (inActiveDocuments) {
   441→        continue;
   442→      }
   443→
   444→      if (inSessionHistory) {
   445→        newLines.push(line);
   446→        if (/^\|\s*-/.test(line) && !headerWritten) {
   447→          newLines.push(`| ${session_num} | ${date} | ${title} | ${commitDisplay} |`);
   448→          headerWritten = true;
   449→        }
   450→        continue;
   451→      }
   452→
   453→      newLines.push(line);
   454→    }
   455→
   456→    writeFileSync(index_path, newLines.join("\n"), "utf-8");
   457→    return true;
   458→  } catch {
   459→    return false;
   460→  }
   461→}
