   518→/**
   519→ * Task directory cache with TTL and LRU eviction
   520→ *
   521→ * Configuration:
   522→ * - TTL: 5 minutes (300,000 ms)
   523→ * - Max size: 1000 entries
   524→ * - Eviction: LRU (least recently used)
   525→ */
   526→const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
   527→const CACHE_MAX_SIZE = 1000;
   528→
   529→interface CacheEntry {
   530→  workspace_path: string;
   531→  task_dir: string;
   532→  /** Timestamp when this entry was last accessed */
   533→  last_accessed: number;
   534→  /** Timestamp when this entry was created */
   535→  created_at: number;
   536→}
   537→
   538→// Store task directory paths by ID for lookups with TTL
   539→const taskDirCache = new Map<string, CacheEntry>();
   540→
   541→/**
   542→ * Get an entry from cache, updating last accessed time
   543→ * Returns null if entry is expired or not found
   544→ */
   545→export function getCacheEntry(taskId: string): CacheEntry | null {
   546→  const entry = taskDirCache.get(taskId);
   547→  if (!entry) return null;
   548→
   549→  const now = Date.now();
   550→  // Check if entry is expired
   551→  if (now - entry.created_at > CACHE_TTL_MS) {
   552→    taskDirCache.delete(taskId);
   553→    return null;
   554→  }
   555→
   556→  // Update last accessed time
   557→  entry.last_accessed = now;
   558→  return entry;
   559→}
   560→
   561→/**
   562→ * Set a cache entry, evicting LRU entries if necessary
   563→ */
   564→export function setCacheEntry(taskId: string, workspacePath: string, taskDir: string): void {
   565→  const now = Date.now();
   566→
   567→  // Evict oldest entries if at capacity
   568→  if (taskDirCache.size >= CACHE_MAX_SIZE) {
   569→    // Find and remove LRU entry
   570→    let oldestKey: string | null = null;
   571→    let oldestTime = Infinity;
   572→
   573→    for (const [key, entry] of taskDirCache) {
   574→      if (entry.last_accessed < oldestTime) {
   575→        oldestTime = entry.last_accessed;
   576→        oldestKey = key;
   577→      }
   578→    }
   579→
   580→    if (oldestKey) {
   581→      taskDirCache.delete(oldestKey);
   582→    }
   583→  }
   584→
   585→  taskDirCache.set(taskId, {
   586→    workspace_path: workspacePath,
   587→    task_dir: taskDir,
   588→    last_accessed: now,
   589→    created_at: now,
   590→  });
   591→}
   592→
   593→/**
   594→ * Remove a task from cache
   595→ */
   596→export function deleteCacheEntry(taskId: string): void {
   597→  taskDirCache.delete(taskId);
   598→}
