     1→/**
     2→ * Idea REST API routes
     3→ *
     4→ * Provides REST-style endpoints for AI-generated idea management:
     5→ * - GET /api/ideas - List all ideas (requires workspace_path)
     6→ * - GET /api/ideas/:id - Get idea by ID
     7→ * - POST /api/ideas/generate - Generate ideas using AI
     8→ * - POST /api/ideas/:id/promote - Promote idea to task
     9→ * - POST /api/ideas/:id/dismiss - Dismiss an idea
    10→ * - DELETE /api/ideas/:id - Remove an idea
    11→ * - DELETE /api/ideas - Remove ideas by type or all
    12→ * - GET /api/idea-types - List available idea types
    13→ *
    14→ * All endpoints share the same src/idea/ops implementation with CLI commands.
    15→ */
    16→import type { FastifyInstance } from "fastify";
    17→import { logger as globalLogger } from "../../telemetry";
    18→
    19→// Import from idea/ops module - shared with CLI
    20→import {
    21→  // Types
    22→  type Idea,
    23→  type IdeaType,
    24→  type EffortLevel,
    25→  type IdeaStatus,
    26→  type IdeaListOptions,
    27→  type IdeaPromoteOptions,
    28→  type IdeaRemoveOptions,
    29→  type IdeaGenerateOptions,
    30→  type IdeaTypeInput,
    31→  EFFORT_LEVELS,
    32→  IDEA_STATUSES,
    33→  // CRUD operations
    34→  listIdeas,
    35→  listTypes,
    36→  viewIdea,
    37→  promoteIdea,
    38→  removeIdeas,
    39→  dismissIdea,
    40→  validateIdeaTypes,
    41→  // Idea Type CRUD operations
    42→  createIdeaTypeOp,
    43→  updateIdeaTypeOp,
    44→  deleteIdeaTypeOp,
    45→  // Generator
    46→  generateIdeas,
    47→} from "../../idea/ops";
    48→
    49→// Module-level logger
    50→const log = globalLogger.child({ module: "ideas" });
    51→
    52→// =============================================================================
    53→// Response Transformers (snake_case for API)
    54→// =============================================================================
    55→
    56→/**
    57→ * Transform Idea to snake_case API response format
    58→ * Note: The Idea interface now uses snake_case internally, so we just need
    59→ * to copy over camelCase optional fields to snake_case
    60→ */
    61→function toSnakeCaseIdea(idea: Idea) {
    62→  return {
    63→    id: idea.id,
    64→    type: idea.type,
    65→    name: idea.name ?? null,
    66→    title: idea.title,
    67→    description: idea.description,
    68→    rationale: idea.rationale,
    69→    estimated_effort: idea.estimatedEffort,
    70→    status: idea.status,
    71→    promoted_to: idea.promotedTo ?? null,
    72→    created_at: idea.created_at,
    73→    // Optional fields (still camelCase in Idea interface)
    74→    affected_files: idea.affectedFiles ?? null,
    75→    existing_patterns: idea.existingPatterns ?? null,
    76→    builds_upon: idea.buildsUpon ?? null,
    77→    implementation_approach: idea.implementationApproach ?? null,
    78→    category: idea.category ?? null,
    79→    severity: idea.severity ?? null,
    80→    target_audience: idea.targetAudience ?? null,
    81→    related_docs: idea.relatedDocs ?? null,
    82→    metrics: idea.metrics ?? null,
    83→    ui_components: idea.uiComponents ?? null,
    84→    user_stories: idea.userStories ?? null,
    85→  };
    86→}
    87→
    88→/**
    89→ * Transform IdeaType to snake_case API response format
    90→ */
    91→function toSnakeCaseIdeaType(ideaType: IdeaType) {
    92→  return {
    93→    name: ideaType.name,
    94→    description: ideaType.description,
    95→    max_ideas: ideaType.maxIdeas ?? null,
    96→    source: ideaType.source,
    97→    prompt_path: ideaType.promptPath,
    98→  };
    99→}
   100→
   101→// =============================================================================
   102→// Route Registration
   103→// =============================================================================
   104→
   105→/**
   106→ * Register idea routes
   107→ */
   108→export function registerIdeaRoutes(fastify: FastifyInstance): void {
   109→  // ============================================================================
   110→  // GET /api/ideas - List all ideas
   111→  // ============================================================================
   112→  fastify.get<{
   113→    Querystring: {
   114→      workspace_path: string;
   115→      type?: string;
   116→      effort?: string;
   117→      status?: string;
   118→    };
   119→  }>("/api/ideas", {
   120→    schema: {
   121→      description: "List all ideas for a workspace with optional filtering",
   122→      tags: ["ideas"],
   123→      querystring: {
   124→        type: "object",
   125→        properties: {
   126→          workspace_path: { type: "string", description: "Workspace path (required)" },
   127→          type: { type: "string", description: "Filter by idea type" },
   128→          effort: {
   129→            type: "string",
   130→            enum: [...EFFORT_LEVELS],
   131→            description: "Filter by effort level",
   132→          },
   133→          status: {
   134→            type: "string",
   135→            enum: [...IDEA_STATUSES],
   136→            description: "Filter by status",
   137→          },
   138→        },
   139→        required: ["workspace_path"],
   140→      },
   141→      response: {
   142→        200: {
   143→          type: "object",
   144→          properties: {
   145→            success: { type: "boolean" },
   146→            ideas: {
   147→              type: "array",
   148→              items: {
   149→                type: "object",
   150→                properties: {
   151→                  id: { type: "string" },
   152→                  type: { type: "string" },
   153→                  name: { type: "string", nullable: true },
   154→                  title: { type: "string" },
   155→                  description: { type: "string" },
   156→                  rationale: { type: "string" },
   157→                  estimated_effort: { type: "string" },
   158→                  status: { type: "string" },
   159→                  promoted_to: { type: "string", nullable: true },
   160→                  created_at: { type: "string" },
   161→                },
   162→              },
   163→            },
   164→            count: { type: "number" },
   165→          },
   166→        },
   167→        400: {
   168→          type: "object",
   169→          properties: {
   170→            success: { type: "boolean" },
   171→            error: { type: "string" },
   172→          },
   173→        },
   174→      },
   175→    },
   176→  }, async (request, reply) => {
   177→    const { workspace_path, type, effort, status } = request.query;
   178→
   179→    if (!workspace_path) {
   180→      reply.code(400);
   181→      return { success: false, error: "workspace_path is required" };
   182→    }
   183→
   184→    log.debug({ workspacePath: workspace_path, type, effort, status }, "Listing ideas");
   185→
   186→    const options: IdeaListOptions = {
   187→      type,
   188→      effort: effort as EffortLevel | undefined,
   189→      status: status as IdeaStatus | undefined,
   190→    };
   191→
   192→    const result = listIdeas(workspace_path, options);
   193→
   194→    if (!result.success) {
   195→      reply.code(400);
   196→      return { success: false, error: result.error };
   197→    }
   198→
   199→    return {
   200→      success: true,
   201→      ideas: result.ideas.map(toSnakeCaseIdea),
   202→      count: result.count,
   203→    };
   204→  });
   205→
   206→  // ============================================================================
   207→  // GET /api/ideas/:id - Get idea by ID
   208→  // ============================================================================
   209→  fastify.get<{
   210→    Params: { id: string };
   211→    Querystring: { workspace_path: string };
   212→  }>("/api/ideas/:id", {
   213→    schema: {
   214→      description: "Get a specific idea by ID",
   215→      tags: ["ideas"],
   216→      params: {
   217→        type: "object",
   218→        properties: {
   219→          id: { type: "string", description: "Idea ID" },
   220→        },
   221→        required: ["id"],
   222→      },
   223→      querystring: {
   224→        type: "object",
   225→        properties: {
   226→          workspace_path: { type: "string", description: "Workspace path (required)" },
   227→        },
   228→        required: ["workspace_path"],
   229→      },
   230→      response: {
   231→        200: {
   232→          type: "object",
   233→          properties: {
   234→            success: { type: "boolean" },
   235→            idea: { type: "object" },
   236→            session_dir: { type: "string", nullable: true },
   237→            file_path: { type: "string", nullable: true },
   238→          },
   239→        },
   240→        404: {
   241→          type: "object",
   242→          properties: {
   243→            success: { type: "boolean" },
   244→            error: { type: "string" },
   245→          },
   246→        },
   247→      },
   248→    },
   249→  }, async (request, reply) => {
   250→    const { id } = request.params;
   251→    const { workspace_path } = request.query;
   252→
   253→    if (!workspace_path) {
   254→      reply.code(400);
   255→      return { success: false, error: "workspace_path is required" };
   256→    }
   257→
   258→    log.debug({ ideaId: id, workspacePath: workspace_path }, "Getting idea");
   259→
   260→    const result = viewIdea(workspace_path, id);
   261→
   262→    if (!result.success || !result.idea) {
   263→      reply.code(404);
   264→      return { success: false, error: result.error || `Idea not found: ${id}` };
   265→    }
   266→
   267→    return {
   268→      success: true,
   269→      idea: toSnakeCaseIdea(result.idea),
   270→      session_dir: result.sessionDir ?? null,
   271→      file_path: result.filePath ?? null,
   272→    };
   273→  });
   274→
   275→  // ============================================================================
   276→  // POST /api/ideas/generate - Generate ideas using AI
   277→  // ============================================================================
   278→  fastify.post<{
   279→    Body: {
   280→      workspace_path: string;
   281→      types: string[];
   282→      output?: string;
   283→      model?: string;
   284→      max_ideas?: number;
   285→      append?: boolean;
   286→      override?: boolean;
   287→    };
   288→  }>("/api/ideas/generate", {
   289→    schema: {
   290→      description: "Generate ideas by analyzing the codebase using AI",
   291→      tags: ["ideas"],
   292→      body: {
   293→        type: "object",
   294→        properties: {
   295→          workspace_path: { type: "string", description: "Workspace path (required)" },
   296→          types: {
   297→            type: "array",
   298→            items: { type: "string" },
   299→            description: "Idea types to generate",
   300→          },
   301→          output: { type: "string", description: "Output directory" },
   302→          model: { type: "string", description: "AI model to use" },
   303→          max_ideas: { type: "number", description: "Maximum ideas per type" },
   304→          append: { type: "boolean", description: "Append to existing ideas" },
   305→          override: { type: "boolean", description: "Force regenerate all types" },
   306→        },
   307→        required: ["workspace_path", "types"],
   308→      },
   309→      response: {
   310→        200: {
   311→          type: "object",
   312→          properties: {
   313→            success: { type: "boolean" },
   314→            session_id: { type: "string" },
   315→            session_dir: { type: "string" },
   316→            ideas: { type: "array", items: { type: "object" } },
   317→            by_type: { type: "object" },
   318→            total_ideas: { type: "number" },
   319→            errors: { type: "array", items: { type: "string" } },
   320→          },
   321→        },
   322→        400: {
   323→          type: "object",
   324→          properties: {
   325→            success: { type: "boolean" },
   326→            error: { type: "string" },
   327→          },
   328→        },
   329→      },
